<script setup>
import RecordPagination from './ui/RecordPagination.vue'
import {usePagination} from '../usePagination.js'
import {computed,ref} from 'vue'
import {api,useLearning} from '../useLearning.js'
import {artwork} from '../assets.js'
import {splitAsset} from '../splitArtwork.js'
const emit=defineEmits(['new-goal'])
const {state,refresh,openCourse,openSession,notify}=useLearning()
const active=ref(0),busy=ref(false),error=ref(''),drafts=ref({}),tab=ref('bridge')
const text=computed({get:()=>drafts.value[active.value]||'',set:value=>{drafts.value[active.value]=value}})
const steps=[{title:'提出预测',art:'notes-notebook',description:'先写下判断，再解释依据。',prompt:'相同张数的纸，平铺、折成波浪或三角支架，哪种更能承重？你为什么这样想？'},{title:'动手实践',art:'paper-fold',description:'控制条件，搭建可比较的结构。',prompt:'你使用了多少张纸？桥面跨度、折叠方式和支撑条件是什么？写下实际制作过程。'},{title:'观察与解释',art:'bridge-load',description:'记下观察，也保留意外。',prompt:'你观察到了什么？请记录实际放置的物体、数量或测量值，并区分观察与解释。'},{title:'反思与改进',art:'notes-pen',description:'用新证据，修改最初的想法。',prompt:'结果是否支持原来的预测？哪些条件还没控制？下一次准备只改变哪个条件？'}]
const materials=[['material-paper','卡纸 / 纸张'],['material-ruler','尺 / 切割垫'],['material-adhesive','胶带 / 胶水'],['material-cutting-tools','铅笔 / 剪刀']]
const project=computed(()=>state.boot?.sessions.find(s=>s.title==='纸桥承重实验'&&s.domain==='跨学科实践'))
const records=computed(()=>(state.boot?.notes||[]).filter(n=>n.session_id===project.value?.id&&n.title.startsWith('项目记录｜')))
async function start(){if(busy.value)return;busy.value=true;error.value='';try{if(!project.value){await api('/sessions',{method:'POST',body:{title:'纸桥承重实验',goal:'通过预测、制作、观察与反思，探究纸张折叠结构和承重表现的关系。',domain:'跨学科实践'}});await refresh()}active.value=0}catch(e){error.value=e.message}finally{busy.value=false}}
async function save(){if(!text.value.trim()||busy.value)return;busy.value=true;error.value='';const savedStage=active.value;try{if(!project.value)throw Error('请先开始项目，再保存实际记录。');await api('/notes',{method:'POST',body:{session_id:project.value.id,title:'项目记录｜纸桥承重实验｜'+steps[active.value].title,text:'阶段：'+steps[active.value].title+'\n\n'+text.value.trim()+'\n\n记录来源：学习者填写的实践记录，尚未经独立核查。'}});drafts.value[savedStage]='';await refresh();notify('实践记录已保存，也可以从笔记与知识空间检索。')}catch(e){error.value=e.message}finally{busy.value=false}}
const {page:recordPage,items:recordRows}=usePagination(records,()=>project.value?.id)
</script>
<template><div class="project-page-live"><div class="studio-pills"><button :class="{active:tab==='bridge'}" @click="tab='bridge'">纸桥实践</button><button :class="{active:tab==='programming'}" @click="tab='programming'">程序推理</button><button @click="emit('new-goal','我想围绕自己的问题设计一个跨学科实践项目')">自选项目</button></div><div v-if="tab==='bridge'" class="project-page-grid"><div class="project-main"><section class="paper-bridge-hero"><div><span class="course-tag apricot">{{ project?'已建立目标':'自编实践模板' }}</span><h2>用纸张，搭一座能承重的桥。</h2><p>从一个预测开始，看看结构、材料和测量如何帮助我们理解真实世界。</p><div class="project-topic-tags"><span>结构与材料</span><span>观察与测量</span><span>解释与反思</span></div><button class="primary-button" :disabled="busy" @click="start">{{ project?'继续项目':'开始这个项目' }}</button></div><img :src="splitAsset('paper-bridge')" alt="纸桥模型插画，非用户实验结果"></section><section class="project-process"><h2>探索步骤</h2><div class="project-step-grid"><button v-for="(step,i) in steps" :key="step.title" :class="{active:active===i}" @click="active=i"><span>{{ i+1 }}</span><img :src="splitAsset(step.art)" alt=""><strong>{{ step.title }}</strong><small>{{ step.description }}</small></button></div><div class="project-record-editor"><h3>{{ steps[active].title }}</h3><p>{{ steps[active].prompt }}</p><textarea v-model="text" aria-label="本阶段实践记录" rows="5" maxlength="20000" placeholder="只记录你实际预测、做过或观察到的内容…"></textarea><p v-if="error" class="inline-error" role="alert">{{ error }}</p><div><small>保存为与项目关联的笔记，不自动判定完成或掌握。</small><button class="primary-button" :disabled="!project||!text.trim()||busy" @click="save">{{ busy?'保存中…':'保存实践记录' }}</button></div></div></section><section v-if="records.length" class="project-saved-records"><h2>已经留下的实践记录</h2><article v-for="record in recordRows" :key="record.id"><h3>{{ record.title.replace('项目记录｜','') }}</h3><p>{{ record.text }}</p><small>{{ new Date(record.updated_at).toLocaleString('zh-CN') }}</small></article><RecordPagination v-model="recordPage" :total="records.length" label="实践记录"/></section></div><aside class="project-page-aside"><section class="studio-side-card mentor-small-card"><h2>项目导师</h2><img :src="artwork.mentor" alt="林知导师"><h3>林知</h3><p>把你的预测、观察和困惑带来，我们一起检查解释。</p><button v-if="project" class="secondary-button" @click="openSession(project.id,null,'buddy')">围绕项目讨论</button><p v-else class="muted-label">开始项目后可围绕目标讨论。</p></section><section class="studio-side-card"><h2>项目材料</h2><div class="project-material-grid"><figure v-for="[image,label] in materials" :key="image"><img :src="splitAsset(image)" :alt="label"><figcaption>{{ label }}</figcaption></figure></div></section><section class="studio-side-card practice-reminder"><h3>先问，再试，再修正。</h3><p>示意模型帮助理解步骤。自己的观察和证据，会从第一次记录开始。</p></section></aside></div><div v-else class="programming-practice-live"><img :src="artwork.programming" alt="程序阅读与预测"><div><span class="course-tag lavender">自编示例单元</span><h2>先预测，再解释。</h2><p>通过变量追踪、条件判断和循环推理检查理解。当前练习不执行用户代码。</p><button class="primary-button" @click="openCourse('programming')">进入程序推理单元</button></div></div></div></template>
